import Head from 'next/head';

function parseCookies(cookieHeader) {
  const list = {};
  if (!cookieHeader) return list;
  cookieHeader.split(';').forEach(function(cookie) {
    const parts = cookie.split('=');
    const key = parts.shift().trim();
    const value = decodeURI(parts.join('='));
    list[key] = value;
  });
  return list;
}

function AuthorizePage({ user }) {
  return (
    <>
      <Head>
        <title>Authorized Page</title>
      </Head>
      <main style={{ padding: 20 }}>
        <h1>Authorized content</h1>
        <p>Welcome{user ? `, ${user}` : ''}! You have access to this protected page.</p>
        <p>
          To sign out, <a href="/api/logout">click here to logout</a> and then refresh.
        </p>
      </main>
    </>
  );
}

export async function getServerSideProps(context) {
  const { req } = context;
  const cookies = parseCookies(req.headers.cookie || '');

  // Compare cookie value with server-side secret
  const authToken = process.env.AUTH_TOKEN;

  if (!authToken || !cookies.auth || cookies.auth !== authToken) {
    // Not authorized -> redirect to login page
    return {
      redirect: {
        destination: '/login',
        permanent: false,
      },
    };
  }

  // Optionally pass user info (demo only)
  return {
    props: {
      user: 'Authorized User',
    },
  };
}

export default AuthorizePage;
